const productos=$('Leer productos para KPIs').all().map(i=>i.json).filter(p=>p.id);const logs=$input.all().map(i=>i.json).filter(p=>p.id);
const counts={};for(const p of productos){const e=p.fields?.['Estado del producto']||'Sin estado';counts[e]=(counts[e]||0)+1;}
const errores=logs.filter(p=>p.fields?.['Registro de errores']).length;
const publicaciones=logs.filter(p=>p.fields?.['Descripción comercial']).length;
const listos=productos.filter(p=>p.fields?.['Resultado de revisión']==='Listo para publicar').length;
const qa=productos.filter(p=>p.fields?.SKU?.startsWith('QA-')).length;
const kpis={actualizado:new Date().toISOString(),productos:productos.length,productos_qa:qa,publicaciones_generadas:publicaciones,errores_registrados:errores,listos_para_publicar:listos,estados:counts};
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cards=[['Productos',kpis.productos],['Borradores generados',publicaciones],['Errores registrados',errores],['Listos para publicar',listos]].map(([l,v])=>`<article><strong>${v}</strong><span>${l}</span></article>`).join('');
const bars=Object.entries(counts).map(([l,v])=>`<tr><td>${esc(l)}</td><td><div class="bar" style="width:${Math.max(2,100*v/Math.max(productos.length,1))}%"></div></td><td>${v}</td></tr>`).join('');
const html=`<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AI Listing Builder | KPIs</title><style>body{margin:0;background:#f3f6fa;color:#17283b;font:16px system-ui,sans-serif}main{max-width:1000px;margin:50px auto;padding:24px}small{color:#516377}h1{font-size:36px;margin:12px 0}section{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:16px;margin:30px 0}article,aside{background:white;border:1px solid #dce4ed;border-radius:12px;padding:24px}strong{display:block;font-size:42px;color:#116e84}span{color:#4d6177}table{width:100%;border-collapse:collapse}td{padding:12px;border-bottom:1px solid #dce4ed}td:nth-child(2){width:48%}.bar{height:14px;background:#1687a1;border-radius:10px}p{line-height:1.6}footer{font-size:13px;margin-top:25px;color:#516377}</style><main><small>CODERHOUSE · AUTOMATIZACIÓN IA</small><h1>AI Listing Builder</h1><p>Panel de operación y revisión humana</p><section>${cards}</section><aside><h2>Estados del proceso</h2><table>${bars}</table></aside><p>Datos reales de Airtable. Incluye ${qa} productos de prueba QA. “Listo para publicar” indica una aprobación registrada; no equivale a una publicación en un marketplace.</p><footer>Actualizado: ${esc(kpis.actualizado)} · Sin nombres de productos, destinatarios, credenciales ni identificadores personales.</footer></main></html>`;
return [{json:{kpis,html}}];
